import java.util.*;

enum HitResult {
    HIT, MISS, SUNK
}

class GameState {
    private int remainingShips;
    private int attacksMade;
    private boolean gameOver;
    private String winner;

    public GameState(int remainingShips, int attacksMade, boolean gameOver, String winner) {
        this.remainingShips = remainingShips;
        this.attacksMade = attacksMade;
        this.gameOver = gameOver;
        this.winner = winner;
    }

    public int getRemainingShips() {
        return remainingShips;
    }

    public int getAttacksMade() {
        return attacksMade;
    }

    public boolean isGameOver() {
        return gameOver;
    }

    public String getWinner() {
        return winner;
    }
}

class StateChange {
    private String eventType;
    private Object data;

    public StateChange(String eventType, Object data) {
        this.eventType = eventType;
        this.data = data;
    }

    public String getEventType() {
        return eventType;
    }

    public Object getData() {
        return data;
    }
}

interface Observer {
    void update(StateChange stateChange);
}

class Observable {
    private List<Observer> observers = new ArrayList<>();

    public void addObserver(Observer observer) {
        observers.add(observer);
    }

    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    protected void notifyObservers(StateChange stateChange) {
        for (Observer observer : observers) {
            observer.update(stateChange);
        }
    }
}

class NavalBattleAdapter extends Observable {
    private Set<String> shipPositions;
    private Set<String> attackPositions;
    private boolean gameOver;
    private String winner;

    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates cannot be null or empty");
        }
        shipPositions.addAll(coordinates);
        notifyStateChange(new StateChange("SHIPS_PLACED", coordinates));
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException("Coordinate cannot be null or empty");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
            shipPositions.remove(coordinate);

            if (shipPositions.isEmpty()) {
                gameOver = true;
                winner = "Opponent";
                notifyStateChange(new StateChange("GAME_OVER", null));
                return HitResult.SUNK;
            }

            notifyStateChange(new StateChange("HIT", coordinate));
            return HitResult.HIT;
        }

        notifyStateChange(new StateChange("MISS", coordinate));
        return HitResult.MISS;
    }

    public GameState getGameState() {
        return new GameState(shipPositions.size(), attackPositions.size(), gameOver, winner);
    }

    public void notifyStateChange(StateChange stateChange) {
        notifyObservers(stateChange);
    }
}

