import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

class KeyValueStore {
    private final ConcurrentHashMap<String, String> store;
    private final ConcurrentHashMap<String, AtomicLong> accessCounts;
    private final ConcurrentHashMap<String, Long> lastAccessTimes;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
    }

    public void put(String key, String value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        store.put(key, value);
        accessCounts.putIfAbsent(key, new AtomicLong(0));
        lastAccessTimes.putIfAbsent(key, 0L);
    }

    public String get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        String value = store.get(key);
        if (value != null) {
            accessCounts.computeIfAbsent(key, k -> new AtomicLong(0)).incrementAndGet();
            lastAccessTimes.put(key, System.currentTimeMillis());
        }

        return value;
    }

    public long getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        AtomicLong count = accessCounts.get(key);
        return count != null ? count.get() : 0;
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        Long lastAccess = lastAccessTimes.get(key);
        return lastAccess != null ? lastAccess : 0;
    }
}

