import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class KeyValueStore {
    private final ConcurrentHashMap<String, Object> store;
    private final ConcurrentHashMap<String, AtomicInteger> accessCounts;
    private final ConcurrentHashMap<String, AtomicLong> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, AtomicInteger> typeCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
        this.typeCounts = new ConcurrentHashMap<>();
    }

    public void put(String key, Object value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Object oldValue = store.put(key, value);

        if (oldValue != null) {
            Class<?> oldType = oldValue.getClass();
            typeCounts.computeIfPresent(oldType, (k, count) -> {
                count.decrementAndGet();
                return count.get() > 0 ? count : null;
            });
        }

        if (value != null) {
            Class<?> newType = value.getClass();
            typeCounts.computeIfAbsent(newType, k -> new AtomicInteger(0)).incrementAndGet();
        }
    }

    public Object get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Object value = store.get(key);

        if (value != null) {
            accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0)).incrementAndGet();
            lastAccessTimes.computeIfAbsent(key, k -> new AtomicLong(0)).set(System.currentTimeMillis());
        }

        return value;
    }

    public int getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicInteger count = accessCounts.get(key);
        return count != null ? count.get() : 0;
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicLong time = lastAccessTimes.get(key);
        return time != null ? time.get() : 0;
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        AtomicInteger count = typeCounts.get(type);
        return count != null ? count.get() : 0;
    }
}

