import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class KeyValueStore {
    private final ConcurrentHashMap<String, Object> store;
    private final ConcurrentHashMap<String, AtomicLong> accessCounts;
    private final ConcurrentHashMap<String, AtomicLong> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, AtomicLong> typeCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
        this.typeCounts = new ConcurrentHashMap<>();
    }

    public void put(String key, Object value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Object oldValue = store.put(key, value);

        if (oldValue != null) {
            Class<?> oldType = oldValue.getClass();
            typeCounts.computeIfAbsent(oldType, k -> new AtomicLong(0)).decrementAndGet();
        }

        if (value != null) {
            Class<?> newType = value.getClass();
            typeCounts.computeIfAbsent(newType, k -> new AtomicLong(0)).incrementAndGet();
        }

        accessCounts.putIfAbsent(key, new AtomicLong(0));
        lastAccessTimes.putIfAbsent(key, new AtomicLong(0));
    }

    public Object get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Object value = store.get(key);

        if (value != null) {
            accessCounts.computeIfAbsent(key, k -> new AtomicLong(0)).incrementAndGet();
            lastAccessTimes.computeIfAbsent(key, k -> new AtomicLong(0)).set(System.currentTimeMillis());
        }

        return value;
    }

    public long getAccessCount(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicLong count = accessCounts.get(key);
        return count != null ? count.get() : 0;
    }

    public long getLastAccessTime(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicLong time = lastAccessTimes.get(key);
        return time != null ? time.get() : 0;
    }

    public long getTypeCount(Class<?> type) {
        if (type == null) {
            return 0;
        }

        AtomicLong count = typeCounts.get(type);
        return count != null ? count.get() : 0;
    }

    public void putAll(Map<String, Object> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries map cannot be null");
        }

        for (Map.Entry<String, Object> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    public Map<String, Object> computeStatistics() {
        Map<String, Object> stats = new HashMap<>();

        stats.put("totalEntries", store.size());

        String maxAccessKey = null;
        long maxAccess = 0;
        for (Map.Entry<String, AtomicLong> entry : accessCounts.entrySet()) {
            long count = entry.getValue().get();
            if (count > maxAccess) {
                maxAccess = count;
                maxAccessKey = entry.getKey();
            }
        }
        stats.put("keyWithMaxAccess", maxAccessKey);

        Map<String, Long> typeDistribution = new HashMap<>();
        for (Map.Entry<Class<?>, AtomicLong> entry : typeCounts.entrySet()) {
            typeDistribution.put(entry.getKey().getName(), entry.getValue().get());
        }
        stats.put("typeDistribution", typeDistribution);

        long estimatedMemory = store.size() * 100;
        stats.put("estimatedMemoryUsage", estimatedMemory);

        return stats;
    }

    public List<String> findKeysByType(Class<?> type) {
        if (type == null) {
            return new ArrayList<>();
        }

        List<String> keys = new ArrayList<>();
        for (Map.Entry<String, Object> entry : store.entrySet()) {
            if (entry.getValue() != null && type.isInstance(entry.getValue())) {
                keys.add(entry.getKey());
            }
        }
        return keys;
    }

    public void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }
}

