import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private Path directoryPath;

    public AdvancedFileProcessor(String path) {
        this.directoryPath = Paths.get(path);
        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory");
        }
    }

    public Map<String, Object> processFiles() throws IOException {
        Map<String, Object> result = new HashMap<>();
        long fileCount = 0;
        long totalSize = 0;
        String largestFile = "N/A";
        long largestFileSize = 0;
        Map<String, Integer> wordFrequency = new HashMap<>();

        try (Stream<Path> paths = Files.walk(directoryPath)) {
            for (Path path : paths.collect(Collectors.toList())) {
                if (Files.isRegularFile(path)) {
                    fileCount++;
                    long size = Files.size(path);
                    totalSize += size;

                    if (size > largestFileSize) {
                        largestFileSize = size;
                        largestFile = path.getFileName().toString();
                    }

                    processFileContent(path, wordFrequency);
                }
            }
        }

        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFile);
        result.put("wordFrequency", sortByValue(wordFrequency));

        return result;
    }

    private void processFileContent(Path file, Map<String, Integer> wordFrequency) throws IOException {
        String content = Files.readString(file);
        String[] words = content.split("\\s+");

        for (String word : words) {
            String cleanedWord = word.toLowerCase().replaceAll("[^a-z]", "");
            if (!cleanedWord.isEmpty()) {
                wordFrequency.put(cleanedWord, wordFrequency.getOrDefault(cleanedWord, 0) + 1);
            }
        }
    }

    private Map<String, Integer> sortByValue(Map<String, Integer> map) {
        return map.entrySet()
                .stream()
                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        Map.Entry::getValue,
                        (e1, e2) -> e1,
                        LinkedHashMap::new
                ));
    }
}

