class StringProcessor {

    public static Map<String, Object> processString(String input) {
        Map<String, Object> results = new HashMap<>();

        // Reverse the entire string
        String reversed = new StringBuilder(input).reverse().toString();
        results.put("reversedString", reversed);

        // Reverse each word individually while maintaining word order
        String[] words = input.split(" ");
        StringBuilder wordsReversed = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            wordsReversed.append(new StringBuilder(words[i]).reverse().toString());
            if (i < words.length - 1) {
                wordsReversed.append(" ");
            }
        }
        results.put("wordsReversed", wordsReversed.toString());

        // Count words, handling multiple consecutive spaces and leading/trailing whitespace
        String trimmed = input.trim();
        int wordCount = 0;
        if (!trimmed.isEmpty()) {
            String[] wordArray = trimmed.split("\\s+");
            wordCount = wordArray.length;
        }
        results.put("wordCount", wordCount);

        return results;
    }
}

