        variables.add(Math.abs(b));

        int notA = -a;
        int notB = -b;

        graph.putIfAbsent(notA, new ArrayList<>());
        graph.get(notA).add(b);

        graph.putIfAbsent(notB, new ArrayList<>());
        graph.get(notB).add(a);
    }

    public boolean isSatisfiable() {
