class TwoSatSolver {
    private Map<Integer, List<Integer>> graph;
    private Map<Integer, List<Integer>> reverseGraph;
    private Set<Integer> variables;

    public TwoSatSolver() {
        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
        variables = new HashSet<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        int notA = -a;
        int notB = -b;

        graph.putIfAbsent(notA, new ArrayList<>());
        graph.get(notA).add(b);

        graph.putIfAbsent(notB, new ArrayList<>());
        graph.get(notB).add(a);

        reverseGraph.putIfAbsent(b, new ArrayList<>());
        reverseGraph.get(b).add(notA);

        reverseGraph.putIfAbsent(a, new ArrayList<>());
        reverseGraph.get(a).add(notB);
